var a=[{title:`Impara il movimento`,text:`Stai in piedi con le ginocchia morbide. Spingi le anche indietro come per chiudere la portiera di un’auto con loro e lascia che il busto si inclini in avanti mentre la schiena resta in una posizione comoda e controllata. Fermati quando i femorali limitano il movimento o il tronco non riesce a restare controllato, poi spingi le anche in avanti per alzarti. Stai allenando il movimento dell’anca, quindi raggiungere il pavimento non è l’obiettivo.`},{title:`Hinge e squat`,text:`Entrambi i movimenti usano anche e ginocchia, con un’enfasi diversa. In uno squat le ginocchia di solito si piegano di più e il busto resta più eretto. In uno stacco rumeno le ginocchia si piegano poco e le anche vanno più indietro, il che mette più lavoro sulla parte posteriore del corpo. Un glute bridge allena l’estensione dell’anca con il busto sostenuto ed è a volte un punto di partenza più facile.`},{title:`Esercizi didattici`,text:`Per il wall tap, stai a un breve passo da un muro e spingi le anche indietro finché lo toccano. Un bastone leggero tenuto lungo la testa, la parte alta della schiena e il bacino può dirti quando la colonna si muove molto. Usa questi esercizi per imparare e non forzare una postura rigida a causa loro.`},{title:`Progressione ed errori`,text:`Inizia con ripetizioni senza carico, poi passa a uno stacco leggero con kettlebell o a uno stacco rumeno con manubri. Tieni il peso vicino e usa un’ampiezza che riesci a controllare. Piegare troppo le ginocchia trasforma il sollevamento in uno squat, e inseguire una profondità fissa può spostare il movimento sulla schiena. Gli swing richiedono più abilità di un hinge lento.`},{title:`Usare TrainUp`,text:`Il tuo piano include esercizi di hinge adatti alla tua attrezzatura e al tuo obiettivo. Se l’equilibrio o una schiena sensibile rendono difficili gli hinge con carico, una variante con appoggio o un ponte per i glutei è un’opzione, e puoi segnalare una limitazione alla schiena nel Profilo. Se il dolore persiste, rivolgiti a un medico o a un fisioterapista invece di costruire un tuo piano di riabilitazione.`}];var o=[{label:`Libreria di esercizi ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`ACE: tecnica dello swing con kettlebell a due mani`,url:`https://www.acefitness.org/continuing-education/certified/january-2025/8788/the-ace-do-it-better-series-the-two-handed-kettlebell-swing/`},{label:`NSCA: sicurezza e fondamenti dell’allenamento coi pesi`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var n={sections:a,sources:o};export{n as default,a as sections,o as sources};